// Node 5 outputs Notion's response, which doesn't have 'ok'
// We'll add it back and keep everything else from Notion's response

return [{
  json: {
    ...($json),           // Spread all Notion response fields
    ok: true,             // Add back the success flag
    notion_updated: true  // Optional: explicit flag for debugging
  }
}];

const scoringData = $json;

// Check if scoring succeeded
if (!scoringData.ok) {
  // Return error state to orchestrator
  return [{
    json: {
      ok: false,
      error: scoringData.error || 'Unknown scoring error',
      job_page_id: scoringData.job_page_id,
      job_url: scoringData.job_url
    }
  }];
}

// Normal success path...
const jobData = $('Node2_prepare_scoring_input').first().json;

return [{
  json: {
    job_page_id: scoringData.job_page_id,
    job_url: scoringData.job_url,
    job_title: jobData.job_title,
    company: jobData.company,
    fit_score: scoringData.fit_score,
    status: scoringData.status,
    analyzed_at: scoringData.analyzed_at,
    analysis_version: scoringData.analysis_version,
    summary: scoringData.summary,
    candidate_page_id: jobData.candidate_page_id,
    candidate_profile: jobData.candidate_profile,
    ok: true
  }
}];

// Just pass through the error data without calling Notion
const errorData = $json;

console.error('⚠️ SKIPPING NOTION UPDATE - Parse/Validation Failed:', {
  job_page_id: errorData.job_page_id,
  job_title: errorData.job_title,
  company: errorData.company,
  job_url: errorData.job_url,
  error_type: errorData.error_type,
