  parse_error: errorData.parse_error,
  validation_errors: errorData.validation_errors,
  timestamp: errorData.timestamp
});

// Return the error data so it appears in execution results
return [{
  json: {
    ...errorData,
    skipped_notion_update: true,
    reason: 'Parse or validation error - Notion not updated to preserve API quota'
  }
}];

const job = $json;
const structured = job.structured_requirements || {};
const canonical = job.candidate_profile_object || {};

let eligible = true;
let reasons = [];

// ------------------------------------
// Experience Check (Master Canonical)
// ------------------------------------

const requiredMinYears = structured.experience?.min_years ?? null;
const candidateYears =
  canonical?.total_experience_years ?? 0;

// Hard upper cap (absolute reject)
const HARD_CAP = 5;

// Experience gap tolerance
const GAP_TOLERANCE = 2.2;

if (typeof requiredMinYears === "number") {

  // Reject very senior roles
  if (requiredMinYears > HARD_CAP) {
    eligible = false;
    reasons.push(
      `Role requires ${requiredMinYears}+ years (exceeds cap ${HARD_CAP})`
    );
  }

  // Reject if gap too large
  if (requiredMinYears - candidateYears > GAP_TOLERANCE) {
    eligible = false;
    reasons.push(
      `Experience gap too large: requires ${requiredMinYears}, candidate has ${candidateYears}`
    );
  }
}

// ------------------------------------
// Offensive Domain Mismatch
// ------------------------------------

const roleCluster = structured.role_cluster_hint || "general";

if (roleCluster === "offensive") {
  eligible = false;
  reasons.push("Offensive security role not aligned with candidate profile");
}

return [{
  json: {
    ...job,
    eligible,
    ineligible_reasons: reasons
  }
}];

const reasonsArray = $input.first().json.ineligible_reasons || [];

const reasonsString = ($json.ineligible_reasons || [])
  .map(r => ` ${r}`)
  .join("\\n");


return [{
  json: {
