// ----------------------------
// Node2: Prepare Scoring Input
// ----------------------------

const jobData = $json;


// ----------------------------
// 1️⃣ Parse structured_requirements safely
// ----------------------------

let structured = {};
const rawStructured = jobData.structured_requirements;

if (typeof rawStructured === "object" && rawStructured !== null) {
  structured = rawStructured;
}
else if (typeof rawStructured === "string" && rawStructured.trim().length > 0) {
  try {
    structured = JSON.parse(rawStructured.trim());
  } catch (e) {
    console.error("structured_requirements parse failed:", e.message);
    structured = {};
  }
}

if (!structured || typeof structured !== "object") structured = {};

if (!Array.isArray(structured.must_have)) structured.must_have = [];
if (!Array.isArray(structured.nice_to_have)) structured.nice_to_have = [];
if (!Array.isArray(structured.hard_constraints)) structured.hard_constraints = [];

if (!structured.experience || typeof structured.experience !== "object") {
  structured.experience = {
    min_years: null,
    seniority_level: "unknown"
  };
}


// ----------------------------
// 2️⃣ Canonical Candidate Profile
// ----------------------------

const candidateProfile = jobData.canonical_profile_object || {};


// ----------------------------
// 3️⃣ Canonical → LLM Projection
// ----------------------------

const flattened = [];

if (candidateProfile.certifications?.length) {
  flattened.push(
    "Certifications:\n- " +
    candidateProfile.certifications.join("\n- ")
  );
}

if (candidateProfile.frameworks?.length) {
  flattened.push(
    "Frameworks:\n- " +
    candidateProfile.frameworks.join("\n- ")
  );
}

if (candidateProfile.tools?.length) {
  flattened.push(
    "Tools & Platforms:\n- " +
    candidateProfile.tools.join("\n- ")
  );
}

if (candidateProfile.skills?.length) {
  flattened.push(
    "Security Capabilities:\n- " +
    candidateProfile.skills.join("\n- ")
  );
}


// ---- Core Capability Sections ----

const core = candidateProfile.core_capabilities || {};

Object.entries(core).forEach(([sectionName, section]) => {

  const items =
    section.activities ||
    section.implementation_depth ||
    section.control_validation ||
    [];

  if (!Array.isArray(items) || items.length === 0) return;

  const formattedSection =
    sectionName
      .replace(/_/g, " ")
      .replace(/\b\w/g, c => c.toUpperCase());

  flattened.push(
    `${formattedSection}:\n- ` +
    items.slice(0,4).join("\n- ")
  );

});

const flattenedCapabilitySummary = flattened.join("\n\n");


// ----------------------------
// 4️⃣ Hard Experience Eligibility
// ----------------------------

const minYearsRequired = structured.experience?.min_years;
const candidateYears =
  candidateProfile?.total_experience_years ?? 0;

let eligible = true;

if (typeof minYearsRequired === "number" && minYearsRequired > 5) {
  eligible = false;
}


// ----------------------------
// 5️⃣ Output
// ----------------------------

return {
  json: {

    eligible,

    job_page_id: jobData.job_page_id,
    job_title: jobData.job_title,
    company: jobData.company,
    job_url: jobData.job_url,
    location: jobData.location,
    posted_date: jobData.posted_date,

    structured_requirements: structured,

    candidate_profile: flattenedCapabilitySummary,   // LLM input
    candidate_profile_object: candidateProfile        // deterministic scoring

  }
};

try {

  // ---- ORIGINAL ENGINE CODE START ----


// =============================
// Deterministic Scoring Engine
// =============================

// =============================
// Deterministic Scoring Engine
// (Self-contained with parser)
// =============================

// 1️⃣ Extract structured + candidate first
const structured = $json.structured_requirements || {};
const candidate = $json.candidate_profile_object || {};

// 2️⃣ Parse LLM qualitative output safely
let llm = {};
let parse_error = false;

try {
  const raw = $json.message?.content || "";
  llm = JSON.parse(raw);
} catch (e) {
  parse_error = true;
  llm = {};
}

// 3️⃣ Safe extraction of arrays
const llmMust = Array.isArray(llm.must_have_requirements)
  ? llm.must_have_requirements
  : [];

const llmNice = Array.isArray(llm.nice_to_have_requirements)
  ? llm.nice_to_have_requirements
  : [];

// 4️⃣ Soft contract mismatch detection
const structuredCount = structured.must_have?.length || 0;
const llmCount = llmMust.length;

const contract_mismatch = structuredCount !== llmCount;

const clamp = (n, min, max) => Math.max(min, Math.min(max, n));

// -----------------------------
// CONFIGURATION (70 / 30)
// -----------------------------

const MAX = {
  A1: 20,
  A2: 35,
  A3: 15,
  B1: 5,
  B2: 18,
  B3: 7,
  PENALTY_CAP: -20
};

// -----------------------------
// A1 EXPERIENCE (Deterministic)
// -----------------------------

const requiredMinYears = structured.experience?.min_years ?? null;
const candidateYears = Number(candidate.total_experience_years || 0);

let A1 = 0;

if (requiredMinYears === null) {
  A1 = candidateYears >= 1 ? 15 : 5;
} else {
  if (candidateYears >= requiredMinYears) A1 = 20;
  else if (candidateYears >= requiredMinYears - 1) A1 = 15;
  else if (candidateYears > 0) A1 = 10;
  else A1 = 0;
}

A1 = clamp(A1, 0, MAX.A1);

// -----------------------------
// A2 CORE TECHNICAL (Anchored to Structured)
// -----------------------------

const structuredMust = Array.isArray(structured.must_have)
  ? structured.must_have
  : [];

// Keep original mustHave for A3 + B1
const mustHave = llmMust.filter(r =>
  r && typeof r === "object"
);

const confidenceMap = {
  high: 5,
  medium: 3,
  low: 1,
  missing: 0
};

function isMatch(structReq, llmReq) {
  const s = structReq.toLowerCase();
  const l = llmReq.toLowerCase();

  return (
    s.includes(l) ||
    l.includes(s)
  );
}

let rawA2 = 0;
let missingMust = 0;

for (const structReq of structuredMust) {

  const match = mustHave.find(llmItem =>
    llmItem &&
    typeof llmItem.requirement === "string" &&
    isMatch(structReq, llmItem.requirement)
  );

  if (match) {
    const conf = typeof match.confidence === "string"
      ? match.confidence
      : "missing";

    rawA2 += confidenceMap[conf] ?? 0;

    if (conf === "missing") missingMust++;

  } else {
    missingMust++;
  }
}

// IMPORTANT: mustCount now refers to structured count
const mustCount = structuredMust.length;
const maxRawA2 = mustCount * 5;

let A2 = 0;

if (maxRawA2 > 0) {
  A2 = Math.round((rawA2 / maxRawA2) * MAX.A2);
}

A2 = clamp(A2, 0, MAX.A2);

// -----------------------------
// A3 COMPLIANCE (Only if present)
// -----------------------------

let A3 = 0;

const complianceKeywords = ["iso", "nist", "soc2", "cis", "csf", "policy", "audit"];

const complianceItems = mustHave.filter(r => {
  if (!r.requirement || typeof r.requirement !== "string") return false;

  return complianceKeywords.some(k =>
    r.requirement.toLowerCase().includes(k)
  );
});

if (complianceItems.length > 0) {
  let raw = 0;
  for (const r of complianceItems) {
    raw += confidenceMap[r.confidence] ?? 0;
  }
  const maxRaw = complianceItems.length * 5;
  A3 = Math.min(raw * 2 , 15);
}

A3 = clamp(A3, 0, MAX.A3);

// -----------------------------
// B1 PROOF QUALITY
// -----------------------------

let strongMatches = mustHave.filter(r => r.confidence === "high").length;

let B1 = 0;

if (strongMatches >= 3) B1 = 5;
else if (strongMatches >= 2) B1 = 3;
else if (strongMatches >= 1) B1 = 2;
else B1 = 0;

B1 = clamp(B1, 0, MAX.B1);

// -----------------------------
// B2 NICE TO HAVE (Scaled)
// -----------------------------

const nice = llm.nice_to_have_requirements || [];
const niceCount = nice.length;

const niceMap = {
  high: 3,
  medium: 2,
  low: 1,
  missing: 0
};

let rawB2 = 0;

for (const r of nice) {
  rawB2 += niceMap[r.confidence] ?? 0;
}

const maxRawB2 = niceCount * 3;
let B2 = 0;

if (maxRawB2 > 0) {
  B2 = Math.round((rawB2 / maxRawB2) * MAX.B2);
}

B2 = clamp(B2, 0, MAX.B2);

// -----------------------------
// B3 CERT BONUS (Deterministic)
// -----------------------------


let B3 = 0;

const certs = Array.isArray(candidate.certifications)
  ? candidate.certifications.join(" ").toLowerCase()
  : "";

if (/google cybersecurity|cissp|ccsp|ceh|iso|aws security/i.test(certs)) {
  B3 = 5;
}

B3 = clamp(B3, 0, MAX.B3);

// -----------------------------
// PENALTIES
// -----------------------------

let penalty = 0;

// >50% must-have missing
if (mustCount > 0 && (missingMust / mustCount) > 0.5) {
  penalty -= 10;
}

// Seniority severe mismatch
if (requiredMinYears !== null && candidateYears + 2 < requiredMinYears) {
  penalty -= 5;
}

penalty = clamp(penalty, MAX.PENALTY_CAP, 0);

// -----------------------------
// FINAL SCORE
// -----------------------------

const baseScore = A1 + A2 + A3 + B1 + B2 + B3;
const fitScore = clamp(baseScore + penalty, 0, 100);

// -----------------------------
// STATUS
// -----------------------------

let status = "Low Fit";
if (fitScore >= 75) status = "Excellent Fit";
else if (fitScore >= 60) status = "Shortlisted";
else if (fitScore >= 40) status = "Moderate Fit";

// -----------------------------
// RETURN
// -----------------------------


return {
  json: {
    fit_score: fitScore,
    base_score: baseScore,
    total_penalties: penalty,
    A1,
    A2,
    A3,
    B1,
    B2,
    B3,
    status,
    contract_mismatch,
    llm_ouput: JSON.parse($json.message.content),
    structured,
    ...$json
  }
};


  // ---- ORIGINAL ENGINE CODE END ----

} catch (err) {
  return {
    json: {
      fatal_error: true,
      error_message: err.message,
      error_stack: err.stack,
      debug_keys: Object.keys($json),
      raw_message: $json.message?.content
    }
  };
}

try {

  const response = $json;
  const content = response.message?.content ?? '';

  const jobPageId = response.job_page_id;
  const jobUrl = response.job_url;
  const jobTitle = response.job_title || 'Unknown Job';
  const company = response.company || 'Unknown Company';

  const structured = response.structured_requirements || {};
  const candidate = response.candidate_profile_object || {};

  const clamp = (n, min, max) => Math.max(min, Math.min(max, n));

  // ----------------------------
  // Parse LLM Output
  // ----------------------------

  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    return {
      json: {
        ok: false,
        error_type: 'parse_error',
        job_page_id: jobPageId,
        fit_score: null,
        status: 'Parse Error'
      }
    };
  }

  if (
    !Array.isArray(parsed.must_have_requirements) ||
    !Array.isArray(parsed.nice_to_have_requirements)
  ) {
    return {
      json: {
        ok: false,
        error_type: 'validation_error',
        job_page_id: jobPageId,
        fit_score: null,
        status: 'Validation Error'
      }
    };
  }

  // ----------------------------
  // Pull Deterministic Scores
  // ----------------------------

  const A1 = response.A1 ?? 0;
  const A2 = response.A2 ?? 0;
  const A3 = response.A3 ?? 0;
  const B1 = response.B1 ?? 0;
  const B2 = response.B2 ?? 0;
  const B3 = response.B3 ?? 0;
  const penalty = response.total_penalties ?? 0;

  const baseScore = A1 + A2 + A3 + B1 + B2 + B3;
  const fitScore = clamp(baseScore + penalty, 0, 100);

  // ----------------------------
  // Status
  // ----------------------------

  let status = "Low Fit";
  if (fitScore >= 75) status = "Excellent Fit";
  else if (fitScore >= 60) status = "Shortlisted";
  else if (fitScore >= 40) status = "Moderate Fit";

  // ----------------------------
  // Human Readable Notes
  // ----------------------------

  const lines = [];

  lines.push(`FIT SCORE: ${fitScore}/100`);
  lines.push(`STATUS: ${status}`);
  lines.push('══════════════════════════════');
  lines.push('');

  lines.push('SCORE BREAKDOWN');
  lines.push('------------------------------');
  lines.push(`A1 Experience            : ${A1}/20`);
  lines.push(`A2 Core Technical        : ${A2}/35`);
  lines.push(`A3 Compliance            : ${A3}/15`);
  lines.push(`B1 Proof Quality         : ${B1}/5`);
  lines.push(`B2 Nice-to-Haves         : ${B2}/18`);
  lines.push(`B3 Certification Bonus   : ${B3}/7`);
  lines.push(`Penalties                : ${penalty}`);
  lines.push(`Base Score               : ${baseScore}/100`);
  lines.push('');

  lines.push(`Required Min Years: ${structured.experience?.min_years ?? 'Not Specified'}`);
  lines.push(`Candidate Years   : ${candidate.total_experience_years ?? 0}`);
  lines.push('');

  lines.push(`MUST-HAVE REQUIREMENTS (${parsed.must_have_requirements.length})`);
  lines.push('------------------------------');

  for (const r of parsed.must_have_requirements) {
    lines.push(`• ${r.requirement}`);
    lines.push(`  Confidence: ${r.confidence}`);
    lines.push(`  Evidence: ${r.resume_evidence || 'N/A'}`);
    lines.push('');
  }

  lines.push(`GOOD-TO-HAVE REQUIREMENTS (${parsed.nice_to_have_requirements.length})`);
  lines.push('------------------------------');

  for (const r of parsed.nice_to_have_requirements) {
    lines.push(`• ${r.requirement}`);
    lines.push(`  Confidence: ${r.confidence}`);
    lines.push(`  Evidence: ${r.resume_evidence || 'N/A'}`);
    lines.push('');
  }

  lines.push('');
  lines.push('SUMMARY');
  lines.push('------------------------------');
  lines.push(parsed.summary || 'No summary provided.');
  lines.push('');
  lines.push(`Analyzed: ${new Date().toISOString()}`);
  lines.push(`Engine Version: fit_engine_v4_dual_layer`);
  lines.push(`Model: qwen2.5`);

  const humanReadableNotes = lines.join('\n');

  // ----------------------------
  // Chunk for Notion
  // ----------------------------

  const chunks = [];
  const maxChunkSize = 1950;

  for (let i = 0; i < humanReadableNotes.length; i += maxChunkSize) {
    chunks.push({
      type: "text",
      text: { content: humanReadableNotes.slice(i, i + maxChunkSize) }
    });
  }
const aiNotesJson = JSON.stringify(parsed, null, 2);

const jsonChunks = [];
for (let i = 0; i < aiNotesJson.length; i += maxChunkSize) {
  jsonChunks.push({
    type: "text",
    text: { content: aiNotesJson.slice(i, i + maxChunkSize) }
  });
}
  // ----------------------------
  // Final Output to Notion
  // ----------------------------
const promptTokens = response.prompt_eval_count ?? null;
const completionTokens = response.eval_count ?? null;
const totalTokens =
  promptTokens !== null && completionTokens !== null
    ? promptTokens + completionTokens
    : null;

const totalDuration = response.total_duration
  ? Number((response.total_duration / 1_000_000_000).toFixed(3))
  : null;

const modelName = response.model ?? "unknown";
  return {
    json: {
      ok: true,
      job_page_id: jobPageId,
      job_url: jobUrl,
      job_title: jobTitle,
      company: company,

      fit_score: fitScore,
      status,

      base_score: baseScore,
      total_penalties: penalty,

      a1_experience_points: A1,
      a2_technical_points: A2,
      a3_compliance_points: A3,
      b1_proof_points: B1,
      b2_nice_to_have_points: B2,
      b3_certification_bonus: B3,

      must_have_count: structured.must_have?.length ?? 0,
      nice_to_have_count: structured.nice_to_have?.length ?? 0,

      ai_notes_chunks: chunks,
      ai_notes_human: humanReadableNotes,
      ai_notes_json_chunks: jsonChunks,

      analyzed_at: new Date().toISOString(),
      analysis_version: "fit_engine_v4_dual_layer",
      llm_prompt_tokens: promptTokens,
llm_completion_tokens: completionTokens,
llm_total_tokens: totalTokens,
llm_total_duration_ms: totalDuration,
llm_model: modelName,
    }
  };

} catch (err) {

  return {
    json: {
      fatal_error: true,
      error_message: err.message,
      error_stack: err.stack
    }
  };

}

// Build clean Notion update payload

return {
  json: {
    page_id: $json.job_page_id,

    body: {
      properties: {

        Job_fit: {
          number: $json.fit_score
        },

        fit_label: {
          select: {
            name: $json.status
          }
        },

        last_analyzed: {
          date: {
            start: $json.analyzed_at
          }
        },

        analysis_version: {
          rich_text: [
            {
              type: "text",
              text: { content: $json.analysis_version }
            }
          ]
        },

        A1_experience: { number: $json.a1_experience_points },
        A2_technical: { number: $json.a2_technical_points },
        A3_compliance: { number: $json.a3_compliance_points },
        B1_proof: { number: $json.b1_proof_points },
        B2_nice: { number: $json.b2_nice_to_have_points },
        B3_cert: { number: $json.b3_certification_bonus },

        base_score: { number: $json.base_score },
        total_penalties: { number: $json.total_penalties },

        llm_total_tokens: { number: $json.llm_total_tokens },
        llm_prompt_tokens: { number: $json.llm_prompt_tokens },
        llm_completion_tokens: { number: $json.llm_completion_tokens },
        llm_duration_ms: { number: $json.llm_total_duration_ms },

        llm_model: {
          rich_text: [
            {
              type: "text",
              text: { content: $json.llm_model || "unknown" }
